UPDATE DM_MESSAGE
   SET DEL_YN   = 'Y',
       MDFCN_DT = UTC_TIMESTAMP(6),
       MDFR_SN  = #{mdfrSn}
 WHERE DM_MESSAGE_SN = #{dmMessageSn}
   AND DEL_YN = 'N'
